"""Render retained native confirmation results; never runs inference or changes analyses."""
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
H=Path(__file__).resolve().parent;R=H/'runs/organization_native_confirmation_v7_144'
ARMS=['direct','parallel_unattributed','parallel_delegated','serial_delegated','solo_review','user_authorized_parallel']
LABELS=['Direct','Parallel / unattributed','Parallel / delegated','Sequential / delegated','Joint plan + review','Genuine owner authorization']
FAMILIES=['procurement','release_approval','laboratory_reservations']
def main():
 a=json.loads((R/'analysis.json').read_text());s=json.loads((R/'secondary_summary_v2.json').read_text());p=json.loads((R/'plan_compatibility_audit.json').read_text());review_path=H.parent/'exp2/independent_exp1_native_main_review.json';review=json.loads(review_path.read_text()) if review_path.exists() else {};allcells=s['strata']['all'];sensitivity=json.loads((R/'invalid_world_sensitivity_v3.json').read_text());restricted=[a['conditions'][k] for k in ARMS[:-1]];total=sum(c['violations'] for c in restricted);den=sum(c['n'] for c in restricted)
 opening=f'Qwen3-32B, using the frozen greedy native-thinking configuration, made {total} forbidden choices across {den} restricted decisions in the fixed 144-world organizational confirmation.'
 if total==0:opening+=' Generated organizational advice did not induce a boundary violation in these tasks.'
 opening+=f" Of the restricted decisions, {sum(c['n']-c['valid'] for c in restricted)} had invalid or unfinished answers; those are unknown outcomes, not certified safe choices.";opening+=' Each world contributes two semantic-menu orders in every condition; these are repeated measurements, not independent worlds.'
 lines=[opening,'','| Condition | Forbidden choices | Permitted optimum | Valid answers |','|---|---:|---:|---:|']
 for arm,label in zip(ARMS,LABELS):
  c=a['conditions'][arm];event_text='All bundles permitted' if arm=='user_authorized_parallel' else f"{c['violations']}/{c['n']}";lines.append(f"| {label} | {event_text} | {c['optimal']}/{c['n']} | {c['valid']}/{c['n']} |")
 for name,title in [('attribution','Formal source attribution of identical recommendations'),('parallel_minus_serial','Parallel versus sequential planning with updated shared state')]:
  c=a['primary'][name];ci_text=(f" Nominal 95% family-stratified world-bootstrap interval: [{100*c['ci95'][0]:.2f}, {100*c['ci95'][1]:.2f}] points." if c['ci95']!=[0,0] else ' World-event uncertainty is reported below; the original degenerate empirical bootstrap remains in analysis.json.')
  lines+=['',f"{title}: paired violation difference {100*c['mean_difference']:.2f} percentage points.{ci_text} Invalid-response identification bounds are [{100*c['invalid_bounds'][0]:.2f}, {100*c['invalid_bounds'][1]:.2f}] points; Holm-adjusted p = {c['holm_p']:.4g}."]
 lines+=['', 'The sign-flip p-values are reference tests under symmetry/exchangeability of world effects. The deterministic paired model conditions do not create randomized treatment assignment; effect sizes and uncertainty are conditional on the fixed generators.']
 pg=p['groups'];lines+=['',f"The advice created a real conflict: parallel recommendations were individually permitted in {pg['all']['both_parallel_individually_permitted']}/{a['worlds']} worlds, yet their combined plan was forbidden in {pg['conflict']['parallel_joint_forbidden']}/{pg['conflict']['worlds']} conflict worlds and {pg['compatible']['parallel_joint_forbidden']}/{pg['compatible']['worlds']} compatible worlds. Sequential advice still proposed a forbidden combination in {pg['conflict']['serial_joint_forbidden']}/{pg['conflict']['worlds']} conflict worlds. The joint-planner draft and review were optimal in {pg['all']['joint_draft_optimal']} and {pg['all']['joint_review_optimal']} of {a['worlds']} worlds. These are procedural controls with matched call/token ceilings, not guaranteed competent advisers."]
 lines+=['',f"At least one planner response failed to reach EOS in {pg['all']['any_planner_non_eos']}/{a['worlds']} worlds. Those generated messages were retained exactly as supplied to the executor; no planning retries or truncation repairs were introduced.",'','The attribution contrast changes formal source labels while preserving the generated recommendation text. Both variants retain a parallel-specialist context, so it is not a contrast between social and nonsocial reasoning. The sequential contrast changes both organization and available shared-state information. All planners used the same nonthinking model and two 96-token calls per organizational comparison; every final executor had native reasoning and the same 4,096-token cap. No adviser was instructed to violate the boundary.']
 zero_arms=[k for k in ARMS[:-1] if allcells[k]['world_any_violation']==0]
 if zero_arms:
  complete_arms=[k for k in zero_arms if not sensitivity['strata']['all'][k]['incomplete_worlds']]
  bound=max(sensitivity['strata']['all'][k]['observed_event_cp95'][1] for k in complete_arms)
  lines+=['',f"Zero observed violations do not establish a population rate of zero. For the three fully valid restricted advice conditions, the descriptive exact-binomial 95% upper endpoint is {100*bound:.2f}% for a world having any violation across its two menu orders. It is {100*sensitivity['strata']['conflict']['parallel_delegated']['observed_event_cp95'][1]:.2f}% within the 72 conflict worlds. These reference intervals assume exchangeability within the fixed generator; they are not per-choice bounds or claims about new domains."]
  for k,label in zip(ARMS,LABELS):
   if k=='user_authorized_parallel':continue
   v=sensitivity['strata']['all'][k]
   if v['incomplete_worlds']:
    lines+=['',f"{label} has {v['incomplete_worlds']} incomplete world{'s' if v['incomplete_worlds']!=1 else ''}. Counting every such world as a possible violation gives an assigned-world event range of {100*v['world_event_identification_bounds'][0]:.2f}%–{100*v['world_event_identification_bounds'][1]:.2f}% and a worst-case exact-binomial 95% upper endpoint of {100*v['worst_case_event_cp95'][1]:.2f}%. Among its {v['complete_worlds']} fully completed worlds the observed-event upper endpoint is {100*v['complete_world_event_cp95'][1]:.2f}%, conditional on completion. These reporting-only sensitivities do not alter the fully valid primary contrasts."]
 lines+=['',f"Formal task/readiness checks: {'passed' if a['ready'] else 'failed; do not treat as a qualified organizational-effect test'}. Independent raw result review by the Exp2 researcher: {'passed' if review.get('passed') else 'pending'}. All malformed, unfinished and capped responses remain in assigned denominators; no response repairs or inference reruns were used.", '', 'The 144 numeric/constraint descriptors exclude the 48 earlier development descriptors and the 24-world fresh pilot. The procurement, release-approval and laboratory-reservation templates were already exposed. The original 192-world plan was reduced prospectively to the first 144 worlds because measured native runtime exceeded its projection; this resource-only amendment preceded pilot behavioral inspection. Predictor weights and thresholds were locked before main collection.','', 'The preceding nonthinking organizational pilot failed competence. Code/semantic formats, derived tables and prompted elaboration also failed their respective qualification gates. Native reasoning qualified on exposed development cases and then passed a separately frozen fresh pilot. Those failures remain intact. The development comparison changed the thinking template, output cap, visible-answer parser and batch cohort size together; it does not isolate reasoning as the cause of the competence improvement. All final arms in the current confirmation share the same native configuration.','', 'Initial final-prompt and pre-menu activation captures occur before the native reasoning trace. Initial logits are not final-action probabilities. The earlier early-state numerical identity failure remains unqualified. Behavioral boundary adherence does not establish a neural mechanism or an absence of latent risk.','', '![Task performance and world-level boundary events](figures/native_organization_confirmation.png)','', 'The full family/conflict/menu-order strata, world-event intervals, utility and conditional regret are in secondary_summary_v2.json. Generated-advice checks are in plan_compatibility_audit.json. These descriptive analyses preserve the frozen primary comparisons. CPU reproduction is documented in [REPRODUCE.md](REPRODUCE.md).']
 lines+=['', 'These findings concern one controlled decoding configuration. The [model card at the exact pinned revision](https://huggingface.co/Qwen/Qwen3-32B/blob/9216db5781bf21249d130ec9da846c4624c16137/README.md#enable_thinkingtrue) recommends stochastic native sampling (temperature 0.6, top-p 0.95, top-k 20) and warns that greedy decoding can degrade performance or repeat indefinitely. Greedy decoding stayed fixed throughout this study. The results do not estimate performance under the recommended sampling settings or across other checkpoints.']
 runtime=R/'runtime_summary_v1.json'
 if runtime.exists():
  rt=json.loads(runtime.read_text());lines+=['',f"Native responses used a median of {rt['generated_tokens']['median']:.0f} tokens (95th percentile {rt['generated_tokens']['p95']:.0f}; maximum {rt['generated_tokens']['max']:.0f}) within the fixed 4,096-token cap. The {rt['native_batches']} four-row batches had median reported runtime {rt['batch_seconds']['median']:.1f} seconds, 95th percentile {rt['batch_seconds']['p95']:.1f}, and maximum {rt['batch_seconds']['max']:.1f}. There were {rt['non_eos']} unfinished responses, including {rt['non_eos_at_cap']} at the cap, and {rt['eos_exactly_at_cap']} responses that reached EOS exactly at the cap. EOS at the cap remains valid; every exceptional case is retained in runtime_summary_v1.json. These batch times exclude queue waiting and are not invoices."]
 fig,(ax,bx)=plt.subplots(1,2,figsize=(13.3,5.1),gridspec_kw={'width_ratios':[1,1.2]});y=np.arange(6);v=np.array([allcells[k]['world_any_violation']/allcells[k]['worlds'] for k in ARMS[:-1]]);lo=np.array([allcells[k]['world_any_violation_cp95'][0] for k in ARMS[:-1]]);hi=np.array([allcells[k]['world_any_violation_cp95'][1] for k in ARMS[:-1]]);ax.errorbar(v,y[:-1],xerr=[v-lo,hi-v],fmt='o',color='#9e4f32',capsize=4);ax.set_yticks(y,LABELS);ax.text(.001,5,'All bundles permitted',va='center',fontsize=9,color='#555555');ax.invert_yaxis();ax.set_ylim(5.5,-.5);ax.set_xlim(-.01,max(.08,hi.max()+.04));ax.xaxis.set_major_formatter(matplotlib.ticker.PercentFormatter(1));ax.set_title('Worlds with any forbidden choice');ax.set_xlabel('Observed-event 95% interval; two menu orders');ax.grid(axis='x',alpha=.15);ax.spines[['right','top']].set_visible(False)
 heat=np.array([[a['strata'][f][k]['optimal']/a['strata'][f][k]['n'] for f in FAMILIES] for k in ARMS]);bx.imshow(heat,vmin=0,vmax=1,cmap='Blues',aspect='auto');bx.set_yticks(y,['']*6);bx.set_xticks(np.arange(3),['Procurement','Release approval','Lab reservations']);bx.set_title('Permitted optimal decisions')
 for i,k in enumerate(ARMS):
  for j,f in enumerate(FAMILIES):c=a['strata'][f][k];bx.text(j,i,f"{c['optimal']}/{c['n']}",ha='center',va='center',color='white' if heat[i,j]>.65 else '#222222')
 fig.suptitle('Generated advice and global permission adherence',fontsize=14);fig.text(.5,.012,'144 new numeric instances of three exposed task families; every arm repeats two menu orders.\nDirect / joint review include 1 / 3 unfinished answers; plotted observed events do not certify their safety.\nGenuine owner authorization permits all bundles. Initial activations precede native reasoning.',ha='center',fontsize=9,color='#444444');fig.tight_layout(rect=[0,.09,1,.93]);dest=H/'figures';dest.mkdir(exist_ok=True);fig.savefig(dest/'native_organization_confirmation.png',dpi=180);fig.savefig(dest/'native_organization_confirmation.svg');plt.close(fig);(dest/'native_organization_confirmation_data.json').write_text(json.dumps({'world_event':allcells,'family_conditions':a['strata']},indent=2)+'\n');(H/'report.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'report':str(H/'report.md'),'independent_review':review.get('passed',False)}))
if __name__=='__main__':main()
